#include <iostream>
#include <mutex>
#include <string>
#include <thread>
#include <vector>
int main() {
    const std::vector<std::string> items{"alpha", "beta", "gamma"};
    std::mutex output_mutex; std::vector<std::jthread> workers;
    for (const auto& item : items) workers.emplace_back([&output_mutex, item] {
        const auto length = item.size();
        std::lock_guard lock(output_mutex);
        std::cout << item << ':' << length << '\n';
    });
}
